const raw = String($input.first().json.domain || '').trim().toLowerCase()
  .replace(/^[a-z]+:\/\//, '').replace(/[\/?#].*$/, '').replace(/\.$/, '');
const re = /^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
if (!re.test(raw)) {
  throw new Error('Invalid domain "' + raw + '". Provide a bare domain such as example.com.');
}
return [{ json: { domain: raw } }];

const domain = $('Validate Domain').first().json.domain;
const run = $input.all().map((i) => i.json).find((j) => j && j.scan_id);
const need = ["discovery_done", "fingerprint_done"];
if (!run) {
  throw new Error('REFUSED: no approved, running scan exists for ' + domain + '. Run discovery first (it requires explicit user approval).');
}
const ageH = (Date.now() - new Date(run.started_at).getTime()) / 3.6e6;
if (ageH > 6) {
  throw new Error('REFUSED: scan ' + run.scan_id + ' is older than 6 hours; a new approval and discovery run are required.');
}
if (!need.includes(run.stage)) {
  throw new Error('REFUSED: scan ' + run.scan_id + ' is at stage "' + run.stage + '"; required stage: ' + need.join(' or ') + '.');
}
return [{ json: { domain, scan_id: run.scan_id } }];

const g = $('Gate').first().json;
const re = /^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const hosts = Array.from(new Set($input.all().map((i) => i.json.host).filter((h) => h && re.test(h)))).slice(0, 500);
return [{ json: { domain: g.domain, scan_id: g.scan_id, hosts, count: hosts.length, targets_b64: Buffer.from(hosts.join('\n')).toString('base64') } }];

const g = $('Build Target List').first().json;
const ssh = $('Run Fingerprint').first().json;
if (ssh.code !== undefined && ssh.code !== 0) {
  throw new Error('Fingerprint script failed (exit ' + ssh.code + '): ' + String(ssh.stderr || '').slice(-800));
}
let out;
try { out = JSON.parse(ssh.stdout); }
catch (e) { throw new Error('Fingerprint output was not valid JSON: ' + String(ssh.stdout || '').slice(0, 300) + ' | stderr: ' + String(ssh.stderr || '').slice(-500)); }
const now = new Date().toISOString();
const profile = (out.nmap && out.nmap.ports_profile) || '';
const docs = (out.hosts || []).map((h) => ({ json: {
  host: h.host,
  http: { services: h.http_services || [], updated_at: now },
  tls: { certificates: h.tls_certificates || [], updated_at: now },
  port_scanning: { ips: h.ips || [], ports_profile: profile, tool: 'nmap -sT -sV --version-light', scanned_at: now },
  fingerprint_scan_id: g.scan_id,
} }));
if (!docs.length) docs.push({ json: { host: '__none__' } });
return docs;

const g = $('Build Target List').first().json;
const out = JSON.parse($('Run Fingerprint').first().json.stdout);
const hosts = out.hosts || [];
const WEB = new Set([80, 443, 3000, 5000, 8000, 8008, 8080, 8081, 8443, 8888, 9000, 9443]);
let services = 0, httpsHosts = 0;
const tech = {}, tlsIssues = [], openSeen = new Set(), nonWeb = [];
for (const h of hosts) {
  services += (h.http_services || []).length;
  if ((h.http_services || []).some((s) => s.scheme === 'https')) httpsHosts++;
  for (const s of (h.http_services || [])) for (const t of (s.tech || [])) tech[t] = (tech[t] || 0) + 1;
  for (const c of (h.tls_certificates || [])) {
    const issues = [];
    if (c.expired) issues.push('expired');
    if (c.self_signed) issues.push('self-signed');
    if (c.mismatched) issues.push('hostname mismatch');
    if (issues.length) tlsIssues.push({ host: h.host, port: c.port, issues });
  }
  for (const ip of (h.ips || [])) for (const p of (ip.open_ports || [])) {
    const k = ip.ip + ':' + p.port;
    if (openSeen.has(k)) continue;
    openSeen.add(k);
    if (!WEB.has(p.port)) nonWeb.push({ ip: ip.ip, port: p.port, service: p.service, product: [p.product, p.version].filter(Boolean).join(' ') || null });
  }
}
const skipped = {};
for (const r of Object.values((out.nmap && out.nmap.skipped) || {})) skipped[r] = (skipped[r] || 0) + 1;
const summary = {
  ok: true,
  stage: 'fingerprinting',
  scan_id: g.scan_id,
  domain: g.domain,
  hosts_requested: g.count,
  hosts_fingerprinted: hosts.length,
  http_services: services,
  https_hosts: httpsHosts,
  tls_issues_count: tlsIssues.length,
  tls_issues: tlsIssues.slice(0, 10),
  ips_scanned_with_nmap: ((out.nmap && out.nmap.scanned) || []).length,
  ips_skipped: skipped,
  unique_open_ports: openSeen.size,
  non_web_open_ports: nonWeb.slice(0, 20),
  top_technologies: Object.entries(tech).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([name, count]) => ({ name, count })),
  warnings: out.warnings || [],
  next_step: 'run_vulnerability_scan',
};
return [{ json: { scan_id: g.scan_id, stage: 'fingerprint_done', updated_at: new Date().toISOString(), fingerprint_summary: summary } }];
